exercise.solution:
def calcular_saldo(produtos, movimentacoes):
    saldos = {produto["id"]: 0 for produto in produtos}
    for movimentacao in movimentacoes:
        produto_id = movimentacao.get("produto_id")
        if produto_id not in saldos:
            continue
        quantidade = movimentacao.get("quantidade", 0)
        if movimentacao.get("tipo") == "saida":
            saldos[produto_id] -= quantidade
        else:
            saldos[produto_id] += quantidade
    return saldos

