def processar_linhas(linhas):
    validos = []
    rejeitados = []

    for numero, linha in enumerate(linhas, start=1):
        sku = (linha.get("sku") or "").strip()
        if not sku:
            rejeitados.append({"linha": numero, "motivo": "sku ausente"})
            continue
        try:
            quantidade = int(linha.get("quantidade"))
        except (TypeError, ValueError):
            rejeitados.append({"linha": numero, "motivo": "quantidade inválida"})
            continue
        if quantidade < 0:
            rejeitados.append({"linha": numero, "motivo": "quantidade inválida"})
            continue
        validos.append({"sku": sku, "quantidade": quantidade})

    return {"validos": validos, "rejeitados": rejeitados}

