exercise.solution:
class Movimentacao:
    TIPOS = ("entrada", "saida")

    def __init__(self, produto_id, quantidade, tipo):
        self.produto_id = produto_id
        self.quantidade = quantidade
        self.tipo = tipo

    def assinado(self):
        return -self.quantidade if self.tipo == "saida" else self.quantidade

    def valida(self):
        if isinstance(self.quantidade, bool) or not isinstance(self.quantidade, int):
            return False
        return self.quantidade > 0 and self.tipo in self.TIPOS

