def filtrar_pedidos(pedidos, status=None, desde=None, ate=None):
    resultado = []
    for pedido in pedidos:
        if status is not None and pedido.get("status") != status:
            continue
        criado_em = pedido.get("criado_em") or ""
        if desde is not None and criado_em < desde:
            continue
        if ate is not None and criado_em > ate:
            continue
        resultado.append(pedido)
    return resultado
